import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import api from '../services/api';

const Dashboard = () => {
  const { user } = useContext(AuthContext);
  const [myProducts, setMyProducts] = useState([]);
  const [categories, setCategories] = useState([]);

  // Поля формы создания товара
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [price, setPrice] = useState('');
  const [category, setCategory] = useState('');
  const [loadingProduct, setLoadingProduct] = useState(false);

  // Поля формы создания категории
  const [newCategoryName, setNewCategoryName] = useState('');
  const [loadingCategory, setLoadingCategory] = useState(false);

  // Загрузка категорий и товаров
  const fetchData = async () => {
    try {
      const [catRes, prodRes] = await Promise.all([
        api.get('categories/'),
        api.get('products/')
      ]);

      setCategories(catRes.data.results || catRes.data);

      const allProducts = prodRes.data.results || prodRes.data;
      const filtered = allProducts.filter(
        (p) => p.owner?.username === user?.username
      );
      setMyProducts(filtered);
    } catch (err) {
      console.error('Ошибка загрузки данных', err);
    }
  };

  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  // Создание новой категории
  const handleCreateCategory = async (e) => {
    e.preventDefault();
    if (!newCategoryName.trim()) return;
    setLoadingCategory(true);
    try {
      await api.post('categories/', { name: newCategoryName });
      setNewCategoryName('');
      await fetchData(); // Обновляем список категорий
      alert('Категория успешно добавлена!');
    } catch (err) {
      console.error('Ошибка создания категории', err);
      alert('Не удалось создать категорию');
    } finally {
      setLoadingCategory(false);
    }
  };

  // Создание нового товара
  const handleCreateProduct = async (e) => {
    e.preventDefault();
    if (!category) {
      alert('Пожалуйста, выберите категорию для товара.');
      return;
    }
    setLoadingProduct(true);
    try {
      await api.post('products/', {
        title,
        description,
        price,
        category: Number(category),
      });
      setTitle('');
      setDescription('');
      setPrice('');
      setCategory('');
      fetchData();
      alert('Товар успешно создан!');
    } catch (err) {
      console.error('Ошибка создания товара', err);
      alert('Не удалось создать товар');
    } finally {
      setLoadingProduct(false);
    }
  };

  // Удаление товара
  const handleDeleteProduct = async (id) => {
    if (window.confirm('Вы уверены, что хотите удалить этот товар?')) {
      try {
        await api.delete(`products/${id}/`);
        fetchData();
      } catch (err) {
        console.error('Ошибка удаления товара', err);
        alert('Не удалось удалить товар');
      }
    }
  };

  return (
    <div style={{ maxWidth: '1100px', margin: '40px auto', padding: '0 20px' }}>
      <h2 style={{ fontSize: '28px', color: '#1a1a1a', marginBottom: '20px' }}>Панель управления продавца</h2>

      {/* Приветствие */}
      <div style={{ background: '#fdfbf7', padding: '20px', borderRadius: '14px', marginBottom: '30px', border: '1px solid #faedcd' }}>
        <p style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#444' }}>
          Добро пожаловать, <strong style={{ color: '#1a1a1a' }}>{user?.username}</strong>!
        </p>
        <p style={{ margin: 0, color: '#8c7a6b', fontSize: '14px' }}>
          Роль в системе: <em style={{ color: '#D97706', fontWeight: 'bold' }}>{user?.role || 'Пользователь'}</em>
        </p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '30px', alignItems: 'start' }}>
        
        {/* Левая колонка: Создание категории + Создание товара */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
          
          {/* Форма быстрого добавления новой категории */}
          <div style={{ background: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #eaeaea', boxShadow: '0 6px 20px rgba(0,0,0,0.04)' }}>
            <h3 style={{ marginTop: 0, marginBottom: '15px', fontSize: '18px', color: '#1a1a1a' }}>Добавить новую категорию</h3>
            <form onSubmit={handleCreateCategory} style={{ display: 'flex', gap: '10px' }}>
              <input
                type="text"
                placeholder="Название категории (напр. Электроника)"
                value={newCategoryName}
                onChange={(e) => setNewCategoryName(e.target.value)}
                required
                style={{ flex: 1, padding: '10px 12px', borderRadius: '8px', border: '1px solid #ced4da', outline: 'none' }}
                onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
                onBlur={(e) => e.target.style.borderColor = '#ced4da'}
              />
              <button
                type="submit"
                disabled={loadingCategory}
                style={{ background: '#1a1a1a', color: '#fff', border: 'none', padding: '10px 16px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}
              >
                {loadingCategory ? '+' : 'Добавить'}
              </button>
            </form>
          </div>

          {/* Форма создания товара */}
          <div style={{ background: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #eaeaea', boxShadow: '0 6px 20px rgba(0,0,0,0.04)' }}>
            <h3 style={{ marginTop: 0, marginBottom: '20px', fontSize: '20px', color: '#1a1a1a' }}>Опубликовать товар</h3>
            <form onSubmit={handleCreateProduct} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' }}>
                  Категория <span style={{ color: '#dc2626' }}>*</span>
                </label>
                <select
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                  required
                  style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ced4da', background: '#fff', outline: 'none' }}
                  onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
                  onBlur={(e) => e.target.style.borderColor = '#ced4da'}
                >
                  <option value="">-- Выберите категорию --</option>
                  {categories.map((cat) => (
                    <option key={cat.id} value={cat.id}>
                      {cat.name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' }}>
                  Название товара:
                </label>
                <input
                  type="text"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  required
                  style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box', outline: 'none' }}
                  onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
                  onBlur={(e) => e.target.style.borderColor = '#ced4da'}
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' }}>
                  Описание:
                </label>
                <textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  required
                  style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box', minHeight: '80px', outline: 'none' }}
                  onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
                  onBlur={(e) => e.target.style.borderColor = '#ced4da'}
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '6px', fontSize: '14px', fontWeight: '600', color: '#444' }}>
                  Цена (₾):
                </label>
                <input
                  type="number"
                  step="0.01"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  required
                  style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box', outline: 'none' }}
                  onFocus={(e) => e.target.style.borderColor = '#F59E0B'}
                  onBlur={(e) => e.target.style.borderColor = '#ced4da'}
                />
              </div>

              <button
                type="submit"
                disabled={loadingProduct}
                style={{
                  background: '#F59E0B',
                  color: '#1a1a1a',
                  border: 'none',
                  padding: '12px',
                  borderRadius: '8px',
                  fontWeight: 'bold',
                  fontSize: '15px',
                  cursor: 'pointer',
                  marginTop: '10px',
                  transition: 'background 0.2s'
                }}
                onMouseEnter={(e) => e.target.style.background = '#E08E0B'}
                onMouseLeave={(e) => e.target.style.background = '#F59E0B'}
              >
                {loadingProduct ? 'Создание...' : 'Опубликовать товар'}
              </button>
            </form>
          </div>
        </div>

        {/* Правая колонка: Список моих товаров */}
        <div>
          <h3 style={{ marginTop: 0, marginBottom: '20px', fontSize: '20px', color: '#1a1a1a' }}>Мои опубликованные товары</h3>
          {myProducts.length > 0 ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              {myProducts.map((prod) => (
                <div
                  key={prod.id}
                  style={{
                    background: '#fff',
                    padding: '20px',
                    borderRadius: '14px',
                    border: '1px solid #eaeaea',
                    boxShadow: '0 4px 12px rgba(0,0,0,0.03)',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center'
                  }}
                >
                  <div>
                    <h4 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1a1a1a' }}>{prod.title}</h4>
                    <p style={{ margin: '0 0 4px 0', color: '#16a34a', fontWeight: 'bold', fontSize: '15px' }}>
                      {prod.price} ₾
                    </p>
                    {prod.category_name && (
                      <span style={{ fontSize: '12px', color: '#D97706', background: '#fdfbf7', padding: '2px 8px', borderRadius: '10px', border: '1px solid #faedcd' }}>
                        {prod.category_name}
                      </span>
                    )}
                  </div>
                  <button
                    onClick={() => handleDeleteProduct(prod.id)}
                    style={{ background: '#fee2e2', color: '#dc2626', border: 'none', padding: '8px 14px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer', transition: 'background 0.2s' }}
                    onMouseEnter={(e) => e.target.style.background = '#fecaca'}
                    onMouseLeave={(e) => e.target.style.background = '#fee2e2'}
                  >
                    Удалить
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <div style={{ background: '#fff', padding: '30px', borderRadius: '16px', border: '1px solid #eaeaea', textAlign: 'center', color: '#888' }}>
              <p style={{ margin: 0 }}>У вас пока нет добавленных товаров.</p>
            </div>
          )}
        </div>

      </div>
    </div>
  );
};

export default Dashboard;
